/**
 * X12 收敛断言（G7-S4）
 * 数据源（model.md）：不变量 INV-1（放行须已认领且正常）remedy.detection
 * 断言：制造违约 ⇒ 等待 ≤ boundMs ⇒ 状态收敛（检测方式：访问策略与归属状态一致性扫描）
 */
import { describe, it, expect } from '@jest/globals';

describe('X12 收敛断言：INV-1 放行须已认领且正常', () => {
  it('制造违约后收敛（boundMs 未声明）', async () => {
    // 制造违约：违反不变量表达式「访问策略=放行 ⇒ 归属状态=已认领 ∧ 处置状态=正常」
    makeViolation('访问策略=放行 ⇒ 归属状态=已认领 ∧ 处置状态=正常');
    // 收敛等待上限未声明（无关联 timing.boundMs）：立即检查 + 显式标注降级
    // 收敛断言：检测方式「访问策略与归属状态一致性扫描」
    await expect(converged('访问策略与归属状态一致性扫描')).resolves.toBe(true);
    expect(elapsed()).toBeGreaterThanOrEqual(0); // 无 boundMs：仅验证收敛发生
  });
});

