/**
 * X15 凭证过期必须失效（G7-S6 / P2-6）
 * 数据源（model.md）：credential: 段凭证 认领码（ttl=待定（建议与未认领资源保留期一致，见待确认 #2））
 * 断言：凭证已过期时验证必须失败（过期 ⇒ 失效，S6-4）
 */
import { describe, it, expect } from '@jest/globals';

describe('X15 凭证过期必须失效：认领码', () => {
  it('凭证 认领码 已过期（ttl=待定（建议与未认领资源保留期一致，见待确认 #2））时验证必须失败', () => {
    // 制造过期：把凭证时间推进到 ttl 有效期之后
    makeCredentialExpired('认领码');
    // 验证凭证：过期 ⇒ 必须失效
    const res = verifyCredential('认领码');
    expect(res.valid).toBe(false);
  });
});

/**
 * X15 凭证已撤销必须失效（G7-S6 / P2-6）
 * 数据源（model.md）：credential: 段凭证 认领码（revoke=资源被移除或封禁即失效；一旦兑付不可再用）
 * 断言：凭证已撤销时验证必须失败（撤销 ⇒ 失效，S6-4）
 */
import { describe, it, expect } from '@jest/globals';

describe('X15 凭证已撤销必须失效：认领码', () => {
  it('凭证 认领码 已撤销（revoke=资源被移除或封禁即失效；一旦兑付不可再用）时验证必须失败', () => {
    // 制造撤销：按撤销语义 资源被移除或封禁即失效；一旦兑付不可再用 撤销凭证
    makeCredentialRevoked('认领码');
    // 验证凭证：已撤销 ⇒ 必须失效
    const res = verifyCredential('认领码');
    expect(res.valid).toBe(false);
  });
});

/**
 * X15 凭证回查失败（G7-S6 / P2-6）
 * 数据源（model.md）：credential: 段凭证 认领码（selfContained=needs-lookup）
 * 断言：回查失败时拒绝而非放行（needs-lookup，S6-3，fail-closed）
 */
import { describe, it, expect } from '@jest/globals';

describe('X15 凭证回查失败：认领码（needs-lookup）', () => {
  it('回查失败时拒绝而非放行（needs-lookup，fail-closed）', () => {
    // 制造回查失败：lookup 端点不可达 / 超时 / 5xx
    simulateLookupFailure('认领码');
    // needs-lookup：凭证需在线回查，回查失败必须拒绝而非放行（S6-3，fail-closed）
    const res = verifyCredential('认领码');
    expect(res.valid).toBe(false);
  });
});
